"use client";
import * as React from "react";
import { cn } from "../lib/cn";
import { Icon } from "../icons/icon";
import { Portal } from "../lib/portal";
import { useAnchorPosition } from "../lib/anchor";
import { useControllableState, useEscapeKey, useOutsideClick, usePresence } from "../lib/hooks";
import { useFieldProps } from "./field";
import { formatDuration, formatTime, parseTime, roundToStep, timeSlots } from "../lib/date";

export interface TimeFieldProps
  extends Omit<React.InputHTMLAttributes<HTMLInputElement>, "value" | "defaultValue" | "onChange" | "size" | "min" | "max" | "step"> {
  /** Tijd in minuten sinds middernacht (09:30 = 570). */
  value?: number | null;
  defaultValue?: number | null;
  onValueChange?: (minutes: number | null) => void;
  /** Stap in minuten voor pijltjestoetsen en suggesties. */
  step?: number;
  /** Vroegste toegestane tijd in minuten. */
  min?: number;
  /** Laatste toegestane tijd in minuten. */
  max?: number;
  size?: "sm" | "md" | "lg";
  invalid?: boolean;
  /** Toont een lijst met tijdstippen bij focus. */
  suggestions?: boolean;
}

/**
 * TimeField — tijd invoeren zonder gedoe: "9", "930", "9.30" en "09:30"
 * worden alle vier begrepen en netjes geformatteerd bij het verlaten van het veld.
 */
export const TimeField = React.forwardRef<HTMLInputElement, TimeFieldProps>(function TimeField(
  {
    value,
    defaultValue = null,
    onValueChange,
    step = 15,
    min = 0,
    max = 23 * 60 + 59,
    size = "md",
    invalid,
    suggestions = true,
    className,
    placeholder = "09:00",
    onBlur,
    onFocus,
    onKeyDown,
    ...rest
  },
  ref
) {
  const [minutes, setMinutes] = useControllableState<number | null>({
    value,
    defaultValue,
    onChange: onValueChange,
  });

  const [text, setText] = React.useState(() => (minutes == null ? "" : formatTime(minutes)));
  const [open, setOpen] = React.useState(false);

  const wrapRef = React.useRef<HTMLDivElement | null>(null);
  const listRef = React.useRef<HTMLDivElement | null>(null);
  const inputRef = React.useRef<HTMLInputElement | null>(null);

  const field = useFieldProps({ invalid, disabled: rest.disabled }) as {
    id?: string;
    disabled?: boolean;
    invalid?: boolean;
    "aria-describedby"?: string;
  };

  const { render: zichtbaar, state: fase } = usePresence(open, listRef, 160);
  const position = useAnchorPosition(wrapRef, listRef, zichtbaar, {
    side: "bottom",
    align: "start",
    offset: 5,
    minWidth: true,
  });

  useEscapeKey(() => setOpen(false), open);
  useOutsideClick([wrapRef, listRef], () => setOpen(false), open);

  React.useEffect(() => {
    setText(minutes == null ? "" : formatTime(minutes));
  }, [minutes]);

  const commit = (raw: string) => {
    if (!raw.trim()) {
      setMinutes(null);
      setText("");
      return;
    }
    const parsed = parseTime(raw);
    if (parsed == null) {
      setText(minutes == null ? "" : formatTime(minutes));
      return;
    }
    const clamped = Math.min(Math.max(parsed, min), max);
    setMinutes(clamped);
    setText(formatTime(clamped));
  };

  const nudge = (direction: 1 | -1) => {
    const base = minutes ?? roundToStep(9 * 60, step);
    const next = Math.min(Math.max(roundToStep(base + direction * step, step), min), max);
    setMinutes(next);
    setText(formatTime(next));
  };

  const slots = React.useMemo(
    () => (suggestions ? timeSlots(roundToStep(min, step), max, step) : []),
    [suggestions, min, max, step]
  );

  const visibleSlots = React.useMemo(() => {
    const needle = text.replace(/\D/g, "");
    if (!needle) return slots;
    const filtered = slots.filter((slot) => formatTime(slot).replace(":", "").startsWith(needle));
    return filtered.length > 0 ? filtered : slots;
  }, [slots, text]);

  React.useEffect(() => {
    if (!open) return;
    const active = listRef.current?.querySelector<HTMLElement>("[data-selected]");
    active?.scrollIntoView({ block: "center" });
  }, [open]);

  return (
    <div className={cn("lui-timefield", className)} ref={wrapRef}>
      <Icon name="clock" size={15} className="lui-timefield-icon" />
      <input
        ref={(node) => {
          inputRef.current = node;
          if (typeof ref === "function") ref(node);
          else if (ref) (ref as React.MutableRefObject<HTMLInputElement | null>).current = node;
        }}
        id={field.id}
        type="text"
        inputMode="numeric"
        autoComplete="off"
        role="combobox"
        aria-expanded={open}
        aria-invalid={field.invalid || undefined}
        aria-describedby={field["aria-describedby"]}
        disabled={field.disabled}
        placeholder={placeholder}
        className={cn(
          "lui-timefield-input",
          `lui-timefield-${size}`,
          field.invalid && "lui-timefield-invalid"
        )}
        value={text}
        onChange={(event) => setText(event.target.value)}
        onFocus={(event) => {
          onFocus?.(event);
          if (suggestions) setOpen(true);
          event.target.select();
        }}
        onBlur={(event) => {
          onBlur?.(event);
          commit(event.target.value);
        }}
        onKeyDown={(event) => {
          onKeyDown?.(event);
          if (event.key === "ArrowUp") {
            event.preventDefault();
            nudge(1);
          } else if (event.key === "ArrowDown") {
            event.preventDefault();
            nudge(-1);
          } else if (event.key === "Enter") {
            event.preventDefault();
            commit((event.target as HTMLInputElement).value);
            setOpen(false);
          } else if (event.key === "Tab") {
            setOpen(false);
          }
        }}
        {...rest}
      />

      {zichtbaar && visibleSlots.length > 0 && (
        <Portal>
          <div
            ref={listRef}
            role="listbox"
            className="lui-timefield-list" data-state={fase} data-side={position.side}
            style={{ ...position.style, opacity: position.ready ? 1 : 0 }}
          >
            {visibleSlots.map((slot) => (
              <button
                key={slot}
                type="button"
                role="option"
                aria-selected={slot === minutes}
                data-selected={slot === minutes ? "" : undefined}
                className="lui-timefield-option"
                onMouseDown={(event) => event.preventDefault()}
                onClick={() => {
                  setMinutes(slot);
                  setText(formatTime(slot));
                  setOpen(false);
                  inputRef.current?.blur();
                }}
              >
                {formatTime(slot)}
              </button>
            ))}
          </div>
        </Portal>
      )}
    </div>
  );
});

export interface TimeRangeValue {
  start: number | null;
  end: number | null;
}

export interface TimeRangeFieldProps {
  value?: TimeRangeValue;
  defaultValue?: TimeRangeValue;
  onValueChange?: (value: TimeRangeValue) => void;
  step?: number;
  min?: number;
  max?: number;
  size?: "sm" | "md" | "lg";
  invalid?: boolean;
  disabled?: boolean;
  className?: string;
  /** Toont de duur rechts van de velden, bv. "7 u 30". */
  showDuration?: boolean;
}

/** TimeRangeField — begin- en eindtijd naast elkaar, met bewaking van de volgorde. */
export const TimeRangeField = React.forwardRef<HTMLDivElement, TimeRangeFieldProps>(
  function TimeRangeField(
    {
      value,
      defaultValue = { start: null, end: null },
      onValueChange,
      step = 15,
      min,
      max,
      size = "md",
      invalid,
      disabled,
      className,
      showDuration = true,
    },
    ref
  ) {
    const [range, setRange] = useControllableState<TimeRangeValue>({
      value,
      defaultValue,
      onChange: onValueChange,
    });

    const duration =
      range.start != null && range.end != null && range.end > range.start
        ? range.end - range.start
        : null;

    return (
      <div ref={ref} className={cn("lui-timerange", className)}>
        <TimeField
          value={range.start}
          onValueChange={(start) => {
            const end = range.end != null && start != null && range.end <= start ? start + step : range.end;
            setRange({ start, end });
          }}
          step={step}
          min={min}
          max={max}
          size={size}
          invalid={invalid}
          disabled={disabled}
          placeholder="Van"
          aria-label="Begintijd"
        />
        <span className="lui-timerange-sep" aria-hidden="true">
          –
        </span>
        <TimeField
          value={range.end}
          onValueChange={(end) => setRange({ ...range, end })}
          step={step}
          min={range.start != null ? range.start + step : min}
          max={max}
          size={size}
          invalid={invalid}
          disabled={disabled}
          placeholder="Tot"
          aria-label="Eindtijd"
        />
        {showDuration && duration != null && (
          <span className="lui-timerange-duration">{formatDuration(duration)}</span>
        )}
      </div>
    );
  }
);

/* ============================ TimeField ============================ */
.lui-timefield { position: relative; display: inline-flex; align-items: center; width: 100%; }
.lui-timefield-icon {
  position: absolute; left: 11px; color: var(--text-3); pointer-events: none;
}

.lui-timefield-input {
  width: 100%; height: calc(42px * var(--density)); padding: 0 12px 0 33px;
  background: var(--surface); color: var(--text);
  border: 1px solid var(--border-strong); border-radius: var(--r-sm);
  font-size: var(--fs-base); font-variant-numeric: tabular-nums;
  outline: none; transition: border-color var(--dur-fast), box-shadow var(--dur-fast);
}
.lui-timefield-input::placeholder { color: var(--text-3); }
.lui-timefield-input:hover:not(:disabled):not(:focus) { border-color: var(--text-3); }
.lui-timefield-input:focus { border-color: var(--accent); box-shadow: var(--ring); }
.lui-timefield-input:disabled { background: var(--surface-3); color: var(--text-2); cursor: not-allowed; }
.lui-timefield-invalid { border-color: var(--red); }
.lui-timefield-invalid:focus { border-color: var(--red); box-shadow: var(--ring-red); }

.lui-timefield-sm { height: calc(34px * var(--density)); padding: 0 9px 0 29px; font-size: 13px; border-radius: var(--r-xs); }
.lui-timefield-lg { height: calc(48px * var(--density)); padding: 0 14px 0 36px; font-size: var(--fs-md); border-radius: var(--r-md); }

.lui-timefield-list {
  z-index: var(--z-popover);
  min-width: 104px; padding: 5px;
  background: var(--surface); border: 1px solid var(--border);
  border-radius: var(--r-md); box-shadow: var(--sh-lg);
  overflow-y: auto; overscroll-behavior: contain;
  animation: lui-menu-in var(--dur-fast) var(--ease) both;
}
.lui-timefield-option {
  display: block; width: 100%; padding: 7px 11px;
  border: none; background: transparent; border-radius: var(--r-xs);
  font: inherit; font-size: 13px; font-variant-numeric: tabular-nums;
  color: var(--text); text-align: left; cursor: pointer;
  transition: background var(--dur-fast);
}
.lui-timefield-option:hover { background: var(--surface-3); }
.lui-timefield-option[data-selected] {
  background: var(--accent-tint); color: var(--accent-active); font-weight: 650;
}

/* ---------- TimeRangeField ---------- */
.lui-timerange { display: flex; align-items: center; gap: 9px; width: 100%; }
.lui-timerange .lui-timefield { flex: 1; min-width: 0; }
.lui-timerange-sep { flex: none; color: var(--text-3); font-size: var(--fs-base); }
.lui-timerange-duration {
  flex: none; font-size: var(--fs-sm); font-weight: 650; color: var(--text-3);
  font-variant-numeric: tabular-nums; white-space: nowrap;
}

/**
 * Datumhulpfuncties — eigen implementatie op basis van de ingebouwde Date en
 * Intl. Geen date-fns, geen dayjs, geen luxon.
 *
 * Alle functies werken met lokale tijd en laten de meegegeven Date ongemoeid.
 */

export interface DateRange {
  from?: Date;
  to?: Date;
}

/** Standaardtaal van het Dafke UI-design. */
export const DEFAULT_LOCALE = "nl-BE";

/* ------------------------------------------------------------------ */
/* Basis                                                               */
/* ------------------------------------------------------------------ */

export function startOfDay(date: Date): Date {
  const copy = new Date(date);
  copy.setHours(0, 0, 0, 0);
  return copy;
}

export function addDays(date: Date, amount: number): Date {
  const copy = new Date(date);
  copy.setDate(copy.getDate() + amount);
  return copy;
}

export function addMonths(date: Date, amount: number): Date {
  const copy = new Date(date);
  const day = copy.getDate();
  copy.setDate(1);
  copy.setMonth(copy.getMonth() + amount);
  copy.setDate(Math.min(day, daysInMonth(copy)));
  return copy;
}

export function daysInMonth(date: Date): number {
  return new Date(date.getFullYear(), date.getMonth() + 1, 0).getDate();
}

export function startOfMonth(date: Date): Date {
  return new Date(date.getFullYear(), date.getMonth(), 1);
}

export function endOfMonth(date: Date): Date {
  return new Date(date.getFullYear(), date.getMonth() + 1, 0, 23, 59, 59, 999);
}

/** weekStartsOn: 0 = zondag, 1 = maandag (standaard in België). */
export function startOfWeek(date: Date, weekStartsOn = 1): Date {
  const copy = startOfDay(date);
  const diff = (copy.getDay() - weekStartsOn + 7) % 7;
  return addDays(copy, -diff);
}

export function endOfWeek(date: Date, weekStartsOn = 1): Date {
  return addDays(startOfWeek(date, weekStartsOn), 6);
}

/* ------------------------------------------------------------------ */
/* Vergelijken                                                         */
/* ------------------------------------------------------------------ */

export function isSameDay(a?: Date | null, b?: Date | null): boolean {
  if (!a || !b) return false;
  return (
    a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate()
  );
}

export function isSameMonth(a?: Date | null, b?: Date | null): boolean {
  if (!a || !b) return false;
  return a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth();
}

export function isToday(date: Date): boolean {
  return isSameDay(date, new Date());
}

export function isWeekend(date: Date): boolean {
  const day = date.getDay();
  return day === 0 || day === 6;
}

export function isBeforeDay(a: Date, b: Date): boolean {
  return startOfDay(a).getTime() < startOfDay(b).getTime();
}

export function isAfterDay(a: Date, b: Date): boolean {
  return startOfDay(a).getTime() > startOfDay(b).getTime();
}

export function isWithin(date: Date, from?: Date | null, to?: Date | null): boolean {
  if (!from || !to) return false;
  const time = startOfDay(date).getTime();
  const start = startOfDay(from).getTime();
  const end = startOfDay(to).getTime();
  return time >= Math.min(start, end) && time <= Math.max(start, end);
}

export function clampDate(date: Date, min?: Date | null, max?: Date | null): Date {
  if (min && isBeforeDay(date, min)) return new Date(min);
  if (max && isAfterDay(date, max)) return new Date(max);
  return date;
}

/** Aantal hele dagen tussen twee datums (b - a). */
export function differenceInDays(a: Date, b: Date): number {
  const millis = startOfDay(b).getTime() - startOfDay(a).getTime();
  return Math.round(millis / 86_400_000);
}

/* ------------------------------------------------------------------ */
/* Weeknummer (ISO 8601)                                               */
/* ------------------------------------------------------------------ */

export function getISOWeek(date: Date): number {
  const target = startOfDay(date);
  // Donderdag van deze week bepaalt het jaar.
  target.setDate(target.getDate() + 3 - ((target.getDay() + 6) % 7));
  const firstThursday = new Date(target.getFullYear(), 0, 4);
  firstThursday.setDate(firstThursday.getDate() + 3 - ((firstThursday.getDay() + 6) % 7));
  return 1 + Math.round((target.getTime() - firstThursday.getTime()) / (7 * 86_400_000));
}

/* ------------------------------------------------------------------ */
/* Rasters                                                             */
/* ------------------------------------------------------------------ */

/** Alle dagen van de maand, aangevuld tot volledige weken (6 × 7 = 42 dagen). */
export function getMonthGrid(month: Date, weekStartsOn = 1): Date[] {
  const first = startOfWeek(startOfMonth(month), weekStartsOn);
  return Array.from({ length: 42 }, (_, index) => addDays(first, index));
}

/** De zeven (of minder) dagen van een week vanaf een datum. */
export function getWeekDays(date: Date, weekStartsOn = 1, length = 7): Date[] {
  const first = startOfWeek(date, weekStartsOn);
  return Array.from({ length }, (_, index) => addDays(first, index));
}

/* ------------------------------------------------------------------ */
/* Formatteren                                                         */
/* ------------------------------------------------------------------ */

const formatterCache = new Map<string, Intl.DateTimeFormat>();

function formatter(locale: string, options: Intl.DateTimeFormatOptions): Intl.DateTimeFormat {
  const key = `${locale}|${JSON.stringify(options)}`;
  let cached = formatterCache.get(key);
  if (!cached) {
    cached = new Intl.DateTimeFormat(locale, options);
    formatterCache.set(key, cached);
  }
  return cached;
}

export function formatDate(
  date: Date,
  options: Intl.DateTimeFormatOptions = { day: "2-digit", month: "short", year: "numeric" },
  locale: string = DEFAULT_LOCALE
): string {
  return formatter(locale, options).format(date);
}

/** "16 – 20 mrt 2026" of "28 feb – 3 mrt 2026" bij een maandgrens. */
export function formatDateRange(range: DateRange, locale: string = DEFAULT_LOCALE): string {
  if (!range.from) return "";
  if (!range.to || isSameDay(range.from, range.to)) return formatDate(range.from, undefined, locale);

  const sameMonth = isSameMonth(range.from, range.to);
  const sameYear = range.from.getFullYear() === range.to.getFullYear();

  const left = formatDate(
    range.from,
    sameMonth
      ? { day: "numeric" }
      : sameYear
        ? { day: "numeric", month: "short" }
        : { day: "numeric", month: "short", year: "numeric" },
    locale
  );
  const right = formatDate(range.to, { day: "numeric", month: "short", year: "numeric" }, locale);
  return `${left} – ${right}`;
}

/** Namen van de weekdagen, beginnend bij weekStartsOn. */
export function weekdayNames(
  weekStartsOn = 1,
  format: "narrow" | "short" | "long" = "short",
  locale: string = DEFAULT_LOCALE
): string[] {
  const base = new Date(2024, 0, 7); // een zondag
  return Array.from({ length: 7 }, (_, index) =>
    formatter(locale, { weekday: format }).format(addDays(base, (index + weekStartsOn) % 7))
  );
}

export function monthName(month: Date, locale: string = DEFAULT_LOCALE): string {
  return formatDate(month, { month: "long", year: "numeric" }, locale);
}

/* ------------------------------------------------------------------ */
/* Tijd (minuten sinds middernacht)                                     */
/* ------------------------------------------------------------------ */

/** "9:30", "930", "9.30" of "0930" → 570. Geeft null bij onleesbare invoer. */
export function parseTime(input: string): number | null {
  const clean = input.trim().replace(/[.,]/g, ":");
  if (!clean) return null;

  const withSeparator = clean.match(/^(\d{1,2}):(\d{1,2})$/);
  if (withSeparator) {
    return toMinutes(Number(withSeparator[1]), Number(withSeparator[2]));
  }

  const digits = clean.replace(/\D/g, "");
  if (!digits) return null;
  if (digits.length <= 2) return toMinutes(Number(digits), 0);
  if (digits.length === 3) return toMinutes(Number(digits.slice(0, 1)), Number(digits.slice(1)));
  return toMinutes(Number(digits.slice(0, 2)), Number(digits.slice(2, 4)));
}

function toMinutes(hours: number, minutes: number): number | null {
  if (!Number.isFinite(hours) || !Number.isFinite(minutes)) return null;
  if (hours > 23 || minutes > 59) return null;
  return hours * 60 + minutes;
}

/** 570 → "09:30". */
export function formatTime(minutes: number): string {
  const total = ((Math.round(minutes) % 1440) + 1440) % 1440;
  const hours = Math.floor(total / 60);
  const rest = total % 60;
  return `${String(hours).padStart(2, "0")}:${String(rest).padStart(2, "0")}`;
}

/** Rondt af op een veelvoud van `step` minuten. */
export function roundToStep(minutes: number, step: number): number {
  if (step <= 0) return minutes;
  return Math.round(minutes / step) * step;
}

/** Alle tijdstippen tussen from en to, met stappen van `step` minuten. */
export function timeSlots(from: number, to: number, step: number): number[] {
  const slots: number[] = [];
  for (let minutes = from; minutes <= to; minutes += step) slots.push(minutes);
  return slots;
}

/** "2 u 30" — leesbare duur voor diensten en verlof. */
export function formatDuration(minutes: number): string {
  const hours = Math.floor(minutes / 60);
  const rest = Math.round(minutes % 60);
  if (hours === 0) return `${rest} min`;
  if (rest === 0) return `${hours} u`;
  return `${hours} u ${rest}`;
}
